import os
import zipfile
from tempfile import mkdtemp, NamedTemporaryFile
from shutil import rmtree
from lxml import etree
from requests import get
from requests.exceptions import MissingSchema


class MissingPackageVersion(Exception):
    """ Package version couldn't be extracted from the TargetBD file """


class TargetBD(object):
    FILE_NAME = 'targetbd'
    SOFTWARE_VERSION = 'softwareReleaseVersion'
    CBTS_SOFTWARE_VERSION = 'cbtsSoftwareReleaseVersion'


class SoftwarePackage(object):
    def __init__(self, bts_sw_path):
        self._artifacts = []
        self.path = self.unzip(bts_sw_path)

    def remove(self):
        for artifact in self._artifacts:
            if os.path.isdir(artifact):
                rmtree(artifact)
            else:
                os.remove(artifact)

    def get_software_versions(self):
        try:
            target_bd_name = [name for name in os.listdir(self.path)
                              if TargetBD.FILE_NAME in name.lower()][0]
            target_bd_path = os.path.join(self.path, target_bd_name)

            with open(target_bd_path, 'r') as target_bd_file:
                content = bytes(target_bd_file.read().encode('utf-8'))
                target_bd = etree.fromstring(content)

            software_version = target_bd.attrib[TargetBD.SOFTWARE_VERSION]
            cbts_software_version = target_bd.attrib[TargetBD.CBTS_SOFTWARE_VERSION]

            return software_version, cbts_software_version
        except (IndexError, KeyError, AttributeError):
            raise MissingPackageVersion

    def unzip(self, bts_sw_path):
        local_package_path = self._download_package(bts_sw_path)

        tmp_dir = mkdtemp()
        zip_ref = zipfile.ZipFile(local_package_path, 'r')
        zip_ref.extractall(path=tmp_dir)
        zip_ref.close()

        unzipped_bts_sw_path = os.path.join(
            tmp_dir, os.listdir(tmp_dir)[0])

        self._artifacts.append(unzipped_bts_sw_path)
        return unzipped_bts_sw_path

    def _download_package(self, bts_sw_path):
        try:
            # Assume the path is an URL
            response = get(bts_sw_path, stream=True)
            tmp_file = NamedTemporaryFile('wb', delete=False, suffix='.zip')

            with open(tmp_file.name, 'wb') as fd:
                for chunk in response.iter_content(chunk_size=128):
                    fd.write(chunk)

            self._artifacts.append(tmp_file.name)
            return tmp_file.name

        except MissingSchema:
            # It's a local path
            return bts_sw_path
